                del pending[:1 + need]
            if status == 'error':
                continue
            if text is not None:
                count = count + len(text)
        elif op == 'finish':
            if status == 'error' or status == 'finished':
                continue
            if len(pending) > 0:
                status = 'error'
                pending = []
            else:
                status = 'finished'
        elif op == 'reset':
            count = 0
            status = 'open'
            pending = []
